class Solution:
    def shortestNetGain(self, changes: List[int], target: int) -> int:
        n = len(changes)
        P = [0] * (n + 1)
        for i, v in enumerate(changes):
            P[i + 1] = P[i] + v
        best, stack = n + 1, []
        for j in range(n + 1):
            lo, hi = 0, len(stack) - 1
            while lo <= hi:
                mid = (lo + hi) // 2
                if P[stack[mid]] <= P[j] - target:
                    best = min(best, j - stack[mid])
                    lo = mid + 1
                else:
                    hi = mid - 1
            while stack and P[stack[-1]] >= P[j]:
                stack.pop()
            stack.append(j)
        return best if best <= n else -1

