class Solution {
    public int shortestNetGain(int[] changes, int target) {
        int n = changes.length;
        long[] P = new long[n + 1];
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + changes[i];
        int[] stack = new int[n + 1];
        int top = 0, best = n + 1;
        for (int j = 0; j <= n; j++) {
            int lo = 0, hi = top - 1;
            while (lo <= hi) {
                int mid = (lo + hi) >>> 1;
                if (P[stack[mid]] <= P[j] - target) { best = Math.min(best, j - stack[mid]); lo = mid + 1; }
                else hi = mid - 1;
            }
            while (top > 0 && P[stack[top - 1]] >= P[j]) top--;
            stack[top++] = j;
        }
        return best <= n ? best : -1;
    }
}

