class Solution {
    public int shortestNetGain(int[] changes, int target) {
        int n = changes.length;
        long[] P = new long[n + 1];
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + changes[i];
        int[] dq = new int[n + 1];
        int head = 0, tail = 0, best = n + 1;
        for (int j = 0; j <= n; j++) {
            while (tail > head && P[j] - P[dq[head]] >= target) best = Math.min(best, j - dq[head++]);
            while (tail > head && P[dq[tail - 1]] >= P[j]) tail--;
            dq[tail++] = j;
        }
        return best <= n ? best : -1;
    }
}

