class Solution {
public:
    int shortestNetGain(vector<int>& changes, int target) {
        int n = changes.size();
        vector<long long> P(n + 1, 0);
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + changes[i];
        deque<int> dq;
        int best = n + 1;
        for (int j = 0; j <= n; j++) {
            while (!dq.empty() && P[j] - P[dq.front()] >= target) {
                best = min(best, j - dq.front());
                dq.pop_front();
            }
            while (!dq.empty() && P[dq.back()] >= P[j]) dq.pop_back();
            dq.push_back(j);
        }
        return best <= n ? best : -1;
    }
};

